import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Corpse-specific WORLD selectors and admission; preserve player replies, ordinary NPC rules and BATTLE. */
public final class CompanionResurrectionMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",ROOT=P+"NativeResurrectionMaterialAction",H=P+"NativeCompanionResurrection",NEG=P+"NativeCompanionNegative";
 static AbstractInsnNode previous(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static MethodInsnNode call(String owner,String name,String desc){return new MethodInsnNode(INVOKESTATIC,owner,name,desc,false);}
 static void selector(MethodNode m,MethodInsnNode snapshot,int iterator){AbstractInsnNode store=snapshot;while(store!=null&&!(store instanceof VarInsnNode v&&v.getOpcode()==ASTORE&&v.var==iterator))store=previous(store);if(store==null||!(previous(store) instanceof MethodInsnNode it&&it.owner.equals("java/util/List")&&it.name.equals("iterator")))throw new AssertionError("corpse owner iterator");var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(call(NEG,"members","(Ljava/util/List;L"+PC+";)Ljava/util/List;"));m.instructions.insertBefore(previous(store),add);m.instructions.insertBefore(snapshot,new VarInsnNode(ALOAD,0));m.instructions.set(snapshot,call(H,"snapshots","(L"+PC+";L"+PC+";)Ljava/util/List;"));}
 static void patch(ClassNode c){
  if(c.name.equals(P+"NativeAreaMaterialAction$Context")){if(c.fields.stream().anyMatch(f->f.name.equals("nativeCorpseTargetScope")))throw new AssertionError("duplicate corpse scope flag");c.fields.add(new FieldNode(0,"nativeCorpseTargetScope","Z",null,null));return;}
  if(c.name.equals(ROOT)){int roots=0,ports=0;for(var m:new ArrayList<>(c.methods)){
   if(Set.of("dispatch","world","admit").contains(m.name)){String name=m.name;var w=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.name="nativeSceneOriginal"+Character.toUpperCase(name.charAt(0))+name.substring(1);for(int i=0;i<(name.equals("admit")?5:3);i++)w.instructions.add(new VarInsnNode(name.equals("admit")&&i>=2?ILOAD:ALOAD,i));w.instructions.add(call(H,name,m.desc));w.instructions.add(new InsnNode(name.equals("admit")?IRETURN:RETURN));c.methods.add(w);roots++;}
   if(m.name.equals("target"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){selector(m,v,6);ports++;}
  }if(roots!=3||ports!=1)throw new AssertionError("resurrection capture ports "+roots+" "+ports);return;}
  int roots=0,ports=0,revives=0,npcRevives=0,sends=0;for(var m:c.methods)if(m.name.equals("nativeMaterialWorldResurrectionBody")){roots++;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v){if(v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){selector(m,v,10);ports++;}else if(v.owner.equals(P+"BattleCompanion")&&v.name.equals("resurrect")){m.instructions.set(v,call(H,"resurrect","(L"+P+"BattleCompanion;I)Z"));revives++;}else if(v.owner.equals(P+"GameHub")&&v.name.equals("resurrectClassicWorldMonster")){m.instructions.set(v,call(H,"resurrectNpc","(L"+P+"GameHub;"+v.desc.substring(1)));npcRevives++;}else if(v.owner.equals(PC)&&v.name.equals("sendEncrypted")){m.instructions.set(v,call(H,"send","(L"+PC+";[BLjava/lang/String;)V"));sends++;}}}if(roots!=1||ports!=1||revives!=1||npcRevives!=1||sends!=11)throw new AssertionError("resurrection WORLD ports "+roots+" "+ports+" "+revives+" "+sends);
  if(c.methods.stream().anyMatch(m->m.name.equals("nativeCorpseSend")))throw new AssertionError("duplicate corpse send bridge");var bridge=new MethodNode(0,"nativeCorpseSend","([BLjava/lang/String;)V",null,new String[]{"java/io/IOException"});for(int i=0;i<3;i++)bridge.instructions.add(new VarInsnNode(ALOAD,i));bridge.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,PC,"sendEncrypted",bridge.desc,false));bridge.instructions.add(new InsnNode(RETURN));c.methods.add(bridge);
 }
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){for(var name:List.of(PC,ROOT,P+"NativeAreaMaterialAction$Context")){var c=read(j,name);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(name+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var candidate=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(candidate,name))))throw new AssertionError(name);}}}System.out.println("PASS exact WORLD corpse capture/selector/revival/publication ports and dedicated ephemeral scope flag; player answer and BATTLE/ordinary NPC bodies retained");}
}
